/* VIP TESTIMONIALS & SPGG SOCIAL PROOF STYLES */
.proof-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin: 28px 0 36px;
}

.proof-stat-card {
  background: linear-gradient(180deg, #0f141d 0%, #090c12 100%);
  border: 1px solid rgba(212, 175, 55, 0.2);
  border-radius: 14px;
  padding: 20px;
  text-align: center;
  box-shadow: 0 10px 25px rgba(0,0,0,0.4);
}

.proof-stat-num {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--gold);
  line-height: 1.1;
  margin-bottom: 4px;
}

.proof-stat-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.72rem;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

/* 3 HEAVYWEIGHT INFLUENCERS SPGG CARDS */
.influencers-spotlight {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 24px;
  margin-bottom: 40px;
}

.influencer-card {
  background: var(--card-bg);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  padding: 24px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 15px 35px rgba(0,0,0,0.5);
  transition: transform 0.25s ease, border-color 0.25s ease;
}

.influencer-card:hover {
  transform: translateY(-4px);
  border-color: var(--gold);
}

.influencer-card.vip-highlight {
  border-color: rgba(212, 175, 55, 0.4);
  background: linear-gradient(180deg, rgba(212, 175, 55, 0.04) 0%, #090c12 100%);
}

.influencer-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
}

.influencer-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--gold), #f59e0b);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 800;
  color: #000;
  font-size: 1.2rem;
  border: 2px solid rgba(255, 255, 255, 0.2);
}

.influencer-meta-name {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.15rem;
  font-weight: 800;
  color: #fff;
}

.influencer-meta-handle {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.75rem;
  color: var(--gold);
}

.influencer-badge-spgg {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.65rem;
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid rgba(16, 185, 129, 0.35);
  color: #6ee7b7;
  padding: 3px 8px;
  border-radius: 4px;
  font-weight: 700;
  display: inline-block;
  margin-top: 4px;
}

.influencer-quote-box {
  background: var(--card-inner);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 16px;
  font-size: 0.9rem;
  color: #e2e8f0;
  line-height: 1.5;
  font-style: italic;
  margin-bottom: 16px;
  position: relative;
}

.influencer-quote-box::before {
  content: '“';
  font-family: 'Cinzel', serif;
  font-size: 2.2rem;
  color: var(--gold);
  position: absolute;
  top: -10px;
  left: 10px;
  opacity: 0.35;
  line-height: 1;
}

.influencer-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: auto;
}

.influencer-tag-chip {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-dim);
  padding: 3px 8px;
  border-radius: 4px;
}

/* 25 TESTIMONIALS ACCORDION / STREAM */
.mini-testis-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
  margin-top: 20px;
}

.mini-testi-card {
  background: var(--card-inner);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mini-testi-author {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.mini-testi-name {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  color: #fff;
}

.mini-testi-role {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.68rem;
  color: var(--cyan);
}

.mini-testi-text {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* SPGG NEED INJECTOR (LAS 4 VERDADES) */
.spgg-need-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin: 30px 0;
}

.spgg-need-card {
  background: var(--card-bg);
  border: 1px solid rgba(212, 175, 55, 0.15);
  border-radius: 16px;
  padding: 22px;
  position: relative;
}

.spgg-need-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.72rem;
  color: var(--crimson);
  font-weight: 700;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

.spgg-need-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.15rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 8px;
}

.spgg-need-desc {
  font-size: 0.86rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* PRINT STYLES FOR ZERO-FRICTION PDF EXPORT */
